<!doctype html>
<html lang="en" class="dark"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="csrf-token" content="{{ csrf_token() }}"><title>{{ $title ?? \App\Models\SiteSetting::value('seo_title', 'GINHAWA // Covenant Network') }}</title><meta name="description" content="{{ \App\Models\SiteSetting::value('seo_description', 'A member-led network for human preservation and community intelligence.') }}"><meta name="keywords" content="{{ \App\Models\SiteSetting::value('seo_keywords', 'Ginhawa, community, preservation, covenant') }}">@if($favicon = \App\Models\SiteSetting::value('site_favicon'))<link rel="icon" href="{{ Storage::disk('public')->url($favicon) }}">@endif<script src="https://cdn.tailwindcss.com"></script><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.1/css/all.min.css"><link href="https://fonts.googleapis.com/css2?family=Courier+Prime:wght@400;700&family=Oswald:wght@500;700&display=swap" rel="stylesheet"><script>tailwind.config={theme:{extend:{colors:{pitch:{950:'#030304',900:'#070708',800:'#0e0e10',700:'#18181c'},silver:{400:'#c0c0c0',500:'#a1a1a6',700:'#636366',800:'#3a3a3c'}},fontFamily:{mono:['Courier Prime','monospace'],oswald:['Oswald','sans-serif']}}}}</script><style>body{background:#030304;color:#f5f5f7;font-family:'Courier Prime',monospace}.scanlines{background:linear-gradient(transparent 50%,rgba(0,0,0,.35) 50%);background-size:100% 4px;pointer-events:none}.chrome{background:linear-gradient(135deg,#fff,#707070,#eee,#fff);-webkit-background-clip:text;background-clip:text;color:transparent}.foil{border:1px solid;border-image:linear-gradient(135deg,#fff,#636366,#eee,#18181c) 1}.hard{box-shadow:5px 5px 0 #c0c0c0}.btn{transition:.15s}.btn:hover{transform:translate(-2px,-2px);box-shadow:5px 5px 0 #c0c0c0}</style></head><body class="min-h-screen bg-pitch-950 selection:bg-silver-400 selection:text-black"><div class="fixed inset-0 scanlines z-50 opacity-25"></div><header class="sticky top-0 z-40 border-b border-silver-800 bg-pitch-950/95 px-4 py-3 backdrop-blur md:px-8"><div class="flex items-center justify-between"><a href="{{ route('home') }}" class="flex items-center gap-3"><span class="bg-white px-2 py-1 font-oswald text-xl text-black">息</span><span><strong class="tracking-[.25em]">{{ \App\Models\SiteSetting::value('site_name', 'GINHAWA') }}</strong><small class="block text-[9px] text-silver-500">{{ \App\Models\SiteSetting::value('site_tagline', '// DECENTRALIZED INTEL NETWORK') }}</small></span></a><nav class="hidden gap-6 text-xs uppercase md:flex"><a href="{{ route('home') }}#directives" class="text-silver-400 hover:text-white">Charter</a><a href="{{ route('community') }}" class="text-silver-400 hover:text-white">Community</a>@auth @if(auth()->user()->hasAnyRole(['administrator','moderator']))<a href="{{ route('admin') }}" class="text-white">Admin</a>@endif @endauth</nav><div class="relative flex items-center gap-3 text-xs">@auth<button type="button" id="notifButton" aria-expanded="false" class="relative px-2 py-1 text-silver-300 hover:text-white"><i class="fa-solid fa-bell"></i><span id="notifCount" class="absolute -right-1 -top-1 hidden min-w-[16px] bg-red-500 px-1 text-center text-[9px] font-bold leading-4 text-black">0</span></button><div id="notifMenu" class="absolute right-0 top-10 z-50 hidden w-80 border border-silver-600 bg-pitch-900 shadow-xl"><div class="flex items-center justify-between border-b border-silver-800 px-3 py-2"><p class="text-[10px] tracking-widest text-silver-500">// TRANSMISSION ALERTS</p><button type="button" id="notifMarkRead" class="text-[9px] text-silver-400 hover:text-white">MARK ALL READ</button></div><div id="notifList" class="max-h-80 overflow-y-auto p-1 text-xs text-silver-400"><p class="px-3 py-3">Loading...</p></div></div><button type="button" id="accountMenuButton" aria-expanded="false" class="flex items-center gap-2 border border-transparent px-2 py-1 text-silver-300 hover:border-silver-700 hover:text-white"><span class="hidden sm:inline">{{ auth()->user()->name }}</span><i class="fa-solid fa-chevron-down text-[9px]"></i></button><div id="accountMenu" class="absolute right-0 top-10 z-50 hidden w-64 border border-silver-600 bg-pitch-900 p-2 shadow-xl"><div class="border-b border-silver-800 px-3 py-3"><p class="text-[10px] tracking-widest text-silver-500">// ACCOUNT CONTROL</p><strong class="mt-1 block text-white">{{ auth()->user()->name }}</strong><span class="text-[10px] text-silver-500">{{ auth()->user()->citizen_number }}</span></div><a href="{{ route('profile') }}" class="block px-3 py-2 text-xs text-silver-300 hover:bg-pitch-800 hover:text-white"><i class="fa-solid fa-id-card mr-2"></i>PROFILE & VERIFICATION</a><a href="{{ route('community') }}" class="block px-3 py-2 text-xs text-silver-300 hover:bg-pitch-800 hover:text-white"><i class="fa-solid fa-satellite-dish mr-2"></i>COMMUNITY</a>@if(auth()->user()->hasAnyRole(['administrator','moderator']))<a href="{{ route('admin') }}" class="block px-3 py-2 text-xs text-silver-300 hover:bg-pitch-800 hover:text-white"><i class="fa-solid fa-sliders mr-2"></i>ADMIN COMMAND</a>@endif<form method="post" action="{{ route('logout') }}" class="border-t border-silver-800 pt-2">@csrf<button class="block w-full px-3 py-2 text-left text-xs text-red-300 hover:bg-pitch-800"><i class="fa-solid fa-arrow-right-from-bracket mr-2"></i>EXIT ACCOUNT</button></form></div>@else<a href="{{ route('login') }}" class="text-silver-300 hover:text-white">LOGIN</a><a href="{{ route('register') }}" class="bg-white px-3 py-1 font-bold text-black">JOIN</a>@endauth</div></div></header>@if(session('success'))<div class="mx-auto max-w-7xl px-4 pt-4"><div class="border border-green-400/50 bg-green-400/10 p-3 text-xs text-green-300">// {{ session('success') }}</div></div>@endif @if($errors->any())<div class="mx-auto max-w-7xl px-4 pt-4"><div class="border border-red-400/50 bg-red-400/10 p-3 text-xs text-red-300">{{ $errors->first() }}</div></div>@endif @yield('content')<footer class="border-t border-silver-800 px-6 py-10 text-center text-[10px] text-silver-600">{{ \App\Models\SiteSetting::value('site_name', 'GINHAWA') }} // AUTHOR: AKHZAROTH KHAN (RICHARD C. CUPAL, LPT)</footer>@stack('scripts')<script>const accountMenuButton=document.getElementById('accountMenuButton'),accountMenu=document.getElementById('accountMenu');if(accountMenuButton&&accountMenu){accountMenuButton.addEventListener('click',()=>{const open=!accountMenu.classList.contains('hidden');accountMenu.classList.toggle('hidden',open);accountMenuButton.setAttribute('aria-expanded',String(!open))});document.addEventListener('click',event=>{if(!accountMenu.contains(event.target)&&!accountMenuButton.contains(event.target)){accountMenu.classList.add('hidden');accountMenuButton.setAttribute('aria-expanded','false')}})}
const notifButton=document.getElementById('notifButton');if(notifButton){const notifMenu=document.getElementById('notifMenu'),notifList=document.getElementById('notifList'),notifCount=document.getElementById('notifCount');let notifOpen=false;const renderNotifs=(data)=>{notifCount.textContent=data.unread>99?'99+':data.unread;notifCount.classList.toggle('hidden',!data.unread);if(!data.notifications.length){notifList.innerHTML='<p class="px-3 py-3 text-silver-600">No alerts yet.</p>';return}notifList.innerHTML=data.notifications.map(n=>'<a href="'+(n.subject_url||'{{ route('community') }}')+'" class="block px-3 py-2 '+(n.unread?'bg-pitch-800 text-white':'')+' hover:bg-pitch-800"><i class="fa-solid '+n.icon+' mr-2 text-[10px]"></i>'+n.label+(n.body?'<span class="block pl-5 text-[10px] text-silver-500">'+n.body+'</span>':'')+'<span class="block pl-5 text-[9px] text-silver-600">'+(n.ago||'')+'</span></a>').join('')};const pollNotifs=async()=>{try{const r=await fetch('{{ route('notifications.index') }}',{headers:{'Accept':'application/json'}});if(r.ok)renderNotifs(await r.json())}catch(e){}};notifButton.addEventListener('click',async()=>{notifOpen=!notifOpen;notifMenu.classList.toggle('hidden',!notifOpen);notifButton.setAttribute('aria-expanded',String(notifOpen));if(notifOpen){await pollNotifs();fetch('{{ route('notifications.readAll') }}',{method:'POST',headers:{'X-CSRF-TOKEN':document.querySelector('meta[name=csrf-token]').content,'Accept':'application/json'}}).then(()=>{notifCount.classList.add('hidden');notifList.querySelectorAll('.bg-pitch-800').forEach(el=>el.classList.remove('bg-pitch-800'))}).catch(e=>{})}});document.addEventListener('click',event=>{if(notifOpen&&!notifMenu.contains(event.target)&&!notifButton.contains(event.target)){notifMenu.classList.add('hidden');notifOpen=false;notifButton.setAttribute('aria-expanded','false')}});pollNotifs();setInterval(pollNotifs,30000)}</script></body></html>
